import sys

def can_form_sequence(a):
    max_val = max(a)
    min_val = min(a)
    range_size = max_val - min_val + 1
    if range_size > 20:
        return "NO"
    b = list(range(min_val, max_val + 1))
    for a_i in a:
        found = False
        for b_j in b:
            for b_k in b:
                if b_j - b_k == a_i:
                    found = True
                    break
            if found:
                break
        if not found:
            return "NO"
    return "YES"

input = sys.stdin.read().strip().split('\n')
t = int(input[0])
index = 1
results = []
for _ in range(t):
    n = int(input[index])
    a = list(map(int, input[index + 1].split()))
    results.append(can_form_sequence(a))
    index += 2
print('\n'.join(results))
